using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Audio;
using UnityEngine.SceneManagement;

namespace AirsoftFPS
{
    // Sound for the whole game. Clips live in Resources/AirsoftAudio (Sfx = one-shots, numbered
    // variations name_1, name_2, ...; Music = loops), all generated by tools/audio/gen_airsoft_audio.py.
    // Everything plays through Resources/AirsoftAudio/AirsoftMixer: Master > SFX / Music / UI, whose
    // volumes follow Settings > Audio (GameSettings).
    //
    // Nothing here is networked. Each peer plays what it can already derive locally: the shot RPCs it
    // receives, the BBs it flies, synced health / objective state, and movement for footsteps.
    //
    // World sounds are 3D (custom roll-off that reaches silence at maxDistance, plus a distance
    // low-pass); UI sounds and your own gun are 2D.
    public static class AirsoftAudio
    {
        public enum Bus { Sfx, Ui, Music }

        const string ROOT = "AirsoftAudio/";
        public const string MIXER = ROOT + "AirsoftMixer";
        // exposed mixer parameters (attenuation in dB), created by Assets/Editor/AirsoftAudioSetup.cs
        public const string P_MASTER = "MasterVolume", P_SFX = "SfxVolume", P_MUSIC = "MusicVolume", P_UI = "UiVolume";

        static AudioHub hub;
        static AudioMixer mixer;
        static AudioMixerGroup gSfx, gUi, gMusic;
        static readonly Dictionary<string, AudioClip[]> banks = new Dictionary<string, AudioClip[]>();
        static readonly Dictionary<string, int> lastPick = new Dictionary<string, int>();
        static readonly Dictionary<string, float> lastPlayed = new Dictionary<string, float>();
        static bool loaded;

        public static AudioMixer Mixer => mixer;
        public static bool HasMixer => mixer != null;
        public static int BankCount => banks.Count;

        // How often each cue has started playing this session (play checks / debugging).
        public static readonly Dictionary<string, int> Played = new Dictionary<string, int>();

        // Domain reload is disabled in the editor: drop state from the last play session.
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        static void ResetStatics()
        {
            hub = null; mixer = null; gSfx = gUi = gMusic = null;
            banks.Clear(); lastPick.Clear(); lastPlayed.Clear(); Played.Clear();
            loaded = false;
            GameAudio.ResetStatics();
            Surfaces.ResetStatics();
        }

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
        static void Boot()
        {
            if (hub != null) return;
            Load();
            var go = new GameObject("~AirsoftAudio");
            Object.DontDestroyOnLoad(go);
            hub = go.AddComponent<AudioHub>();
            hub.Init(gSfx, gUi, gMusic);
            GameSettings.Changed -= ApplyVolumes;
            GameSettings.Changed += ApplyVolumes;
            ApplyVolumes();
        }

        static void Load()
        {
            if (loaded) return;
            loaded = true;
            mixer = Resources.Load<AudioMixer>(MIXER);
            if (mixer != null)
            {
                gSfx = Group("SFX");
                gUi = Group("UI");
                gMusic = Group("Music");
            }
            else Debug.LogWarning("[Airsoft] audio mixer missing (Resources/" + MIXER + "); volumes fall back to AudioListener.volume");

            var lists = new Dictionary<string, List<AudioClip>>();
            foreach (var c in Resources.LoadAll<AudioClip>(ROOT + "Sfx"))
            {
                string key = BankName(c.name);
                if (!lists.TryGetValue(key, out var l)) lists[key] = l = new List<AudioClip>();
                l.Add(c);
            }
            foreach (var kv in lists)
            {
                kv.Value.Sort((a, b) => string.CompareOrdinal(a.name, b.name));
                banks[kv.Key] = kv.Value.ToArray();
            }
        }

        static AudioMixerGroup Group(string name)
        {
            var found = mixer.FindMatchingGroups(name);
            foreach (var g in found) if (g.name == name) return g;
            return found.Length > 0 ? found[0] : null;
        }

        // "shot_aeg_3" -> "shot_aeg"; "hitmarker" -> "hitmarker"
        static string BankName(string clip)
        {
            int u = clip.LastIndexOf('_');
            if (u > 0 && u < clip.Length - 1)
            {
                bool digits = true;
                for (int i = u + 1; i < clip.Length; i++) if (!char.IsDigit(clip[i])) { digits = false; break; }
                if (digits) return clip.Substring(0, u);
            }
            return clip;
        }

        // ───────────────────────── volumes ─────────────────────────
        public static void ApplyVolumes()
        {
            GameSettings.EnsureLoaded();
            if (mixer == null) { AudioListener.volume = GameSettings.MasterVolume; return; }
            AudioListener.volume = 1f;
            mixer.SetFloat(P_MASTER, ToDb(GameSettings.MasterVolume));
            mixer.SetFloat(P_SFX, ToDb(GameSettings.SfxVolume));
            mixer.SetFloat(P_MUSIC, ToDb(GameSettings.MusicVolume));
            mixer.SetFloat(P_UI, ToDb(GameSettings.AnnouncerVolume));
            hub?.RefreshFallbackVolumes();
        }

        // Slider 0..1 -> mixer dB (perceptually even: 50% = -12 dB, 0 = off).
        public static float ToDb(float v) => v <= 0.0001f ? -80f : Mathf.Max(-80f, 40f * Mathf.Log10(v));

        // Without a mixer the buses still need their own level.
        internal static float FallbackBusVolume(Bus bus) =>
            mixer != null ? 1f
            : bus == Bus.Music ? GameSettings.MusicVolume : bus == Bus.Ui ? GameSettings.AnnouncerVolume : GameSettings.SfxVolume;

        // ───────────────────────── clips ─────────────────────────
        public static bool Has(string cue) => banks.ContainsKey(cue);

        public static AudioClip Clip(string cue, int variation = -1)
        {
            if (!banks.TryGetValue(cue, out var arr) || arr.Length == 0) return null;
            if (variation >= 0) return arr[variation % arr.Length];
            if (arr.Length == 1) return arr[0];
            lastPick.TryGetValue(cue, out int last);
            int i = Random.Range(0, arr.Length - 1);
            if (i >= last) i++;              // never the same variation twice in a row
            lastPick[cue] = i;
            return arr[i];
        }

        public static AudioClip MusicClip(string name) => Resources.Load<AudioClip>(ROOT + "Music/" + name);

        static bool Throttled(string key, float minInterval)
        {
            if (minInterval <= 0f) return false;
            float now = Time.unscaledTime;
            if (lastPlayed.TryGetValue(key, out float t) && now - t < minInterval) return true;
            lastPlayed[key] = now;
            return false;
        }

        // ───────────────────────── playback ─────────────────────────
        // 2D one-shot (UI, your own gun / body).
        public static AudioSource Play2D(string cue, float volume = 1f, Bus bus = Bus.Ui, float pitchJitter = 0f,
                                         float minInterval = 0f, int variation = -1)
        {
            if (hub == null || Throttled(cue, minInterval)) return null;
            var clip = Clip(cue, variation);
            if (clip == null) return null;
            Count(cue);
            return hub.Play(clip, Vector3.zero, false, volume, 1f + Random.Range(-pitchJitter, pitchJitter), bus, 0f, 0f);
        }

        // 3D one-shot in the world. minDist = full volume inside; silent at maxDist.
        public static AudioSource PlayAt(string cue, Vector3 pos, float volume = 1f, float minDist = 2f, float maxDist = 40f,
                                         float pitchJitter = 0.05f, float minInterval = 0f, int variation = -1,
                                         Bus bus = Bus.Sfx)
        {
            if (hub == null || Throttled(cue, minInterval)) return null;
            if (!hub.Audible(pos, maxDist)) return null;
            var clip = Clip(cue, variation);
            if (clip == null) return null;
            Count(cue);
            return hub.Play(clip, pos, true, volume, 1f + Random.Range(-pitchJitter, pitchJitter), bus, minDist, maxDist);
        }

        static void Count(string cue)
        {
            Played.TryGetValue(cue, out int n);
            Played[cue] = n + 1;
        }

        // ───────────────────────── game sounds ─────────────────────────
        public static string ShotKind(WeaponData w) => w != null && !string.IsNullOrEmpty(w.sound) ? w.sound : "aeg";

        // A trigger pull. own = the local player's gun (2D, close); otherwise 3D at the shooter.
        public static void Shot(WeaponData w, Vector3 pos, bool own)
        {
            string kind = ShotKind(w);
            float loud; float range;
            switch (kind)
            {
                case "sniper":     loud = 1.0f;  range = 95f; break;
                case "springbolt": loud = 0.9f;  range = 85f; break;
                case "shotgun":    loud = 0.95f; range = 75f; break;
                case "co2":        loud = 0.85f; range = 65f; break;
                case "gbb":        loud = 0.8f;  range = 60f; break;
                default:           loud = 0.75f; range = 65f; break;   // AEG
            }
            if (own) Play2D("shot_" + kind, loud * 0.85f, Bus.Sfx, 0.03f);
            else PlayAt("shot_" + kind, pos, loud, 3f, range, 0.04f);
        }

        // A BB hit something (every peer flies its own copy of every BB, so each impact plays once per peer).
        public static void Impact(RaycastHit hit)
        {
            var s = Surfaces.Of(hit.collider);
            switch (s)
            {
                case Surfaces.Kind.Body:  PlayAt("impact_body", hit.point, 0.9f, 1.5f, 30f, 0.08f, 0.02f); break;
                case Surfaces.Kind.Metal: PlayAt("impact_metal", hit.point, 0.55f, 1f, 30f, 0.1f, 0.02f); break;
                case Surfaces.Kind.Wood:  PlayAt("impact_wood", hit.point, 0.6f, 1f, 22f, 0.1f, 0.02f); break;
                case Surfaces.Kind.Glass: PlayAt("impact_glass", hit.point, 0.45f, 1f, 25f, 0.1f, 0.02f); break;
                case Surfaces.Kind.Soft:  PlayAt("impact_soft", hit.point, 0.5f, 1f, 15f, 0.1f, 0.02f); break;
                default:                  PlayAt("impact_concrete", hit.point, 0.55f, 1f, 22f, 0.1f, 0.02f); break;
            }
        }

        public static string StepCue(Surfaces.Kind k) => k switch
        {
            Surfaces.Kind.Metal => "step_metal",
            Surfaces.Kind.Wood => "step_wood",
            Surfaces.Kind.Soft => "step_grass",
            _ => "step_concrete",
        };

        // Health hooks (every peer, from the NetworkVariable callbacks).
        public static void OnHealthChanged(Health h, int prev, int curr)
        {
            if (h == null || curr >= prev || curr <= 0) return;
            if (IsLocalPlayer(h)) Play2D("hurt", 0.75f, Bus.Sfx, 0.05f, 0.08f);
        }

        public static void OnDeadChanged(Health h, bool dead)
        {
            if (h == null) return;
            bool local = IsLocalPlayer(h);
            if (dead)
            {
                if (local) Play2D("eliminated", 0.8f);
                else PlayAt("down", h.transform.position + Vector3.up * 0.5f, 0.9f, 2f, 35f);
            }
            else if (local) Play2D("respawn", 0.45f);
        }

        // Milsim / Medic: the hit player calls "HIT!" (each player keeps their own voice).
        public static void OnHitChanged(Health h, bool hit)
        {
            if (h == null) return;
            bool local = IsLocalPlayer(h);
            if (hit)
            {
                PlayAt("hit_call", h.transform.position + Vector3.up * 1.6f, 1f, 4f, 70f, 0.02f, 0f, (int)(h.MatchId % 4));
                if (local) Play2D("hurt", 0.6f, Bus.Sfx, 0.05f);
            }
            else if (local && h.IsSpawned && !h.isDead.Value) Play2D("respawn", 0.45f);
        }

        public static bool IsLocalPlayer(Health h) => h != null && h.isPlayer && h.IsSpawned && h.IsOwner && !h.IsBot;

        // ───────────────────────── UI ─────────────────────────
        public static void UiHover() => Play2D("ui_hover", 0.35f, Bus.Ui, 0.02f, 0.04f);
        public static void UiClick(UIKit.Btn style)
        {
            switch (style)
            {
                case UIKit.Btn.Danger: Play2D("ui_back", 0.6f, Bus.Ui, 0f, 0.03f); break;
                case UIKit.Btn.Tab:
                case UIKit.Btn.Segment: Play2D("ui_toggle", 0.55f, Bus.Ui, 0f, 0.03f); break;
                case UIKit.Btn.Primary: Play2D("ui_click", 0.75f, Bus.Ui, 0f, 0.03f); break;
                default: Play2D("ui_click", 0.6f, Bus.Ui, 0f, 0.03f); break;
            }
        }

        // ───────────────────────── music ─────────────────────────
        // null = silence. Ambience plays on the SFX bus (it's part of the world), music on Music.
        public static void SetMusic(string clip, float volume, Bus bus) => hub?.SetMusic(clip, volume, bus);

        public static string CurrentMusic => hub != null ? hub.MusicName : null;
        public static bool MusicPlaying => hub != null && hub.MusicPlaying;

        internal static AudioHub Hub => hub;
    }

    // Owns the voices (pooled AudioSources) and the two music players; runs GameAudio every frame.
    public class AudioHub : MonoBehaviour
    {
        const int VOICES_3D = 40;
        const int VOICES_2D = 14;

        class Voice
        {
            public AudioSource src;
            public AudioLowPassFilter lpf;
            public float started;
            public AirsoftAudio.Bus bus;
            public float baseVolume;
        }

        readonly List<Voice> voices3D = new List<Voice>();
        readonly List<Voice> voices2D = new List<Voice>();
        AudioMixerGroup gSfx, gUi, gMusic;

        AudioSource musicA, musicB;      // crossfade pair
        string musicName;
        float musicVol;
        AirsoftAudio.Bus musicBus;
        float musicVolB;                 // the outgoing track keeps its own volume and bus while it fades
        AirsoftAudio.Bus musicBusB;
        float fadeA, fadeB;              // current fade levels (0..1)

        AudioListener listener;
        float nextListenerSearch;

        public string MusicName => musicName;
        public bool MusicPlaying => musicA != null && musicA.isPlaying;

        static readonly Dictionary<int, AnimationCurve> s_rolloff = new Dictionary<int, AnimationCurve>();

        public void Init(AudioMixerGroup sfx, AudioMixerGroup ui, AudioMixerGroup music)
        {
            gSfx = sfx; gUi = ui; gMusic = music;
            for (int i = 0; i < VOICES_3D; i++) voices3D.Add(MakeVoice("v3d_" + i, true));
            for (int i = 0; i < VOICES_2D; i++) voices2D.Add(MakeVoice("v2d_" + i, false));
            musicA = MakeMusic("musicA");
            musicB = MakeMusic("musicB");
        }

        Voice MakeVoice(string name, bool spatial)
        {
            var go = new GameObject(name);
            go.transform.SetParent(transform, false);
            var v = new Voice { src = go.AddComponent<AudioSource>() };
            v.src.playOnAwake = false;
            v.src.dopplerLevel = 0f;
            v.src.spatialBlend = spatial ? 1f : 0f;
            v.src.rolloffMode = AudioRolloffMode.Custom;
            v.src.spread = 0f;
            if (spatial)
            {
                v.lpf = go.AddComponent<AudioLowPassFilter>();
                v.lpf.cutoffFrequency = 22000f;
            }
            return v;
        }

        AudioSource MakeMusic(string name)
        {
            var go = new GameObject(name);
            go.transform.SetParent(transform, false);
            var s = go.AddComponent<AudioSource>();
            s.playOnAwake = false;
            s.loop = true;
            s.spatialBlend = 0f;
            s.priority = 0;
            s.volume = 0f;
            return s;
        }

        AudioMixerGroup GroupOf(AirsoftAudio.Bus bus) => bus == AirsoftAudio.Bus.Ui ? gUi : bus == AirsoftAudio.Bus.Music ? gMusic : gSfx;

        // ───────────────────────── one-shots ─────────────────────────
        public AudioSource Play(AudioClip clip, Vector3 pos, bool spatial, float volume, float pitch, AirsoftAudio.Bus bus,
                                float minDist, float maxDist)
        {
            var list = spatial ? voices3D : voices2D;
            Voice v = null;
            float oldest = float.MaxValue;
            foreach (var c in list)
            {
                if (!c.src.isPlaying) { v = c; break; }
                if (c.started < oldest) { oldest = c.started; v = c; }   // all busy: steal the oldest
            }
            if (v == null) return null;

            var s = v.src;
            s.Stop();
            s.clip = clip;
            s.outputAudioMixerGroup = GroupOf(bus);
            v.bus = bus;
            v.baseVolume = volume;
            s.volume = volume * AirsoftAudio.FallbackBusVolume(bus);
            s.pitch = pitch;
            s.priority = spatial ? 128 : 64;
            if (spatial)
            {
                s.transform.position = pos;
                s.minDistance = Mathf.Max(0.1f, minDist);
                s.maxDistance = Mathf.Max(s.minDistance + 1f, maxDist);
                s.SetCustomCurve(AudioSourceCurveType.CustomRolloff, Rolloff(s.minDistance / s.maxDistance));
                // distant sounds lose their highs (air absorption / masking by the world)
                float d = ListenerDistance(pos);
                float k = Mathf.InverseLerp(10f, Mathf.Max(20f, s.maxDistance * 0.9f), d);
                v.lpf.cutoffFrequency = Mathf.Lerp(22000f, 2200f, Mathf.Sqrt(k));
            }
            v.started = Time.unscaledTime;
            s.Play();
            return s;
        }

        // Inverse-distance roll-off (like Unity's logarithmic one) that fades to silence at maxDistance.
        static AnimationCurve Rolloff(float ratio)
        {
            int key = Mathf.RoundToInt(ratio * 1000f);
            if (s_rolloff.TryGetValue(key, out var c)) return c;
            ratio = Mathf.Clamp(key / 1000f, 0.001f, 0.9f);
            var keys = new List<Keyframe> { new Keyframe(0f, 1f), new Keyframe(ratio, 1f) };
            for (float x = ratio * 1.5f; x < 1f; x *= 1.5f)
            {
                float fade = 1f - Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(0.55f, 1f, x));
                keys.Add(new Keyframe(x, ratio / x * fade));
            }
            keys.Add(new Keyframe(1f, 0f));
            c = new AnimationCurve(keys.ToArray());
            for (int i = 0; i < c.length; i++) c.SmoothTangents(i, 0f);
            s_rolloff[key] = c;
            return c;
        }

        public bool Audible(Vector3 pos, float maxDist)
        {
            var l = Listener();
            return l == null || (l.transform.position - pos).sqrMagnitude < maxDist * maxDist;
        }

        float ListenerDistance(Vector3 pos)
        {
            var l = Listener();
            return l != null ? Vector3.Distance(l.transform.position, pos) : 0f;
        }

        AudioListener Listener()
        {
            if (listener != null && listener.isActiveAndEnabled) return listener;
            if (Time.unscaledTime < nextListenerSearch) return listener;
            nextListenerSearch = Time.unscaledTime + 0.5f;
            listener = null;
            foreach (var l in FindObjectsByType<AudioListener>())
                if (l.isActiveAndEnabled) { listener = l; break; }
            return listener;
        }

        public void RefreshFallbackVolumes()
        {
            foreach (var v in voices3D) if (v.src.isPlaying) v.src.volume = v.baseVolume * AirsoftAudio.FallbackBusVolume(v.bus);
            foreach (var v in voices2D) if (v.src.isPlaying) v.src.volume = v.baseVolume * AirsoftAudio.FallbackBusVolume(v.bus);
        }

        // ───────────────────────── music ─────────────────────────
        public void SetMusic(string name, float volume, AirsoftAudio.Bus bus)
        {
            if (name == musicName) { musicVol = volume; musicBus = bus; return; }
            musicVolB = musicVol;
            musicBusB = musicBus;
            musicVol = volume;
            musicBus = bus;
            musicName = name;
            // the old track fades out on B, the new one starts on A
            (musicA, musicB) = (musicB, musicA);
            (fadeA, fadeB) = (fadeB, fadeA);
            if (string.IsNullOrEmpty(name)) { musicA.Stop(); fadeA = 0f; return; }
            var clip = AirsoftAudio.MusicClip(name);
            if (clip == null) { musicA.Stop(); fadeA = 0f; return; }
            musicA.clip = clip;
            musicA.outputAudioMixerGroup = GroupOf(bus);
            fadeA = 0f;
            musicA.volume = 0f;
            musicA.Play();
        }

        void UpdateMusic(float dt)
        {
            fadeA = Mathf.MoveTowards(fadeA, musicA.clip != null && musicA.isPlaying ? 1f : 0f, dt / 1.5f);
            fadeB = Mathf.MoveTowards(fadeB, 0f, dt / 1.5f);
            musicA.volume = musicVol * fadeA * AirsoftAudio.FallbackBusVolume(musicBus);
            musicB.volume = musicVolB * fadeB * AirsoftAudio.FallbackBusVolume(musicBusB);
            if (fadeB <= 0f && musicB.isPlaying) musicB.Stop();
        }

        bool volumesApplied;

        void Update()
        {
            // exposed mixer parameters set before the first frame don't always stick: set them again
            if (!volumesApplied) { volumesApplied = true; AirsoftAudio.ApplyVolumes(); }
            float dt = Time.unscaledDeltaTime;
            try { GameAudio.Tick(); }
            catch (System.Exception e) { Debug.LogException(e); }
            UpdateMusic(dt);
        }
    }
}
